# 支付策略函数
def credit_pay(amount):
    print(f"使用信用卡支付 {amount} 元")
    return True

def paypal_pay(amount):
    print(f"使用 PayPal 支付 {amount} 元")
    return True

# 工厂函数
def get_payment_strategy(method):
    strategies = {
        'credit': credit_pay,
        'paypal': paypal_pay
    }
    return strategies.get(method)

# 观察者模式
class PaymentProcess:
    def __init__(self):
        self._observers = []

    def register(self, observer):
        self._observers.append(observer)

    def unregister(self, observer):
        self._observers.remove(observer)

    def notify(self, amount, method):
        for obs in self._observers:
            obs(amount, method)

    def pay(self, amount, method):
        strategy = get_payment_strategy(method)
        if strategy:
            success = strategy(amount)
            if success:
                print("支付成功")
                self.notify(amount, method)
        else:
            print("不支持的支付方式")

# 观察者函数
def log_observer(amount, method):
    print(f"[LOG] 支付 {amount} 元，方式 {method}")

def email_observer(amount, method):
    print(f"[EMAIL] 已发送支付确认邮件，金额 {amount} 元，方式 {method}")

# 演示
if __name__ == "__main__":
    processor = PaymentProcess()
    processor.register(log_observer)
    processor.register(email_observer)
    processor.pay(100, 'credit')
